// ---------- Builder's Handbook (glossary) ----------
const GLOSSARY = {
  general_contractor: ['General Contractor (GC)', 'The boss of the building project! The GC hires workers, orders materials, keeps the schedule and budget, and makes sure it is all built right. That\'s YOU!'],
  subcontractor: ['Subcontractor', 'A company the GC hires to do one special job, like plumbing or roofing. People call them "subs."'],
  bid: ['Bid', 'The price a subcontractor offers to do a job. Smart builders compare a few bids — cheapest is not always best!'],
  budget: ['Budget', 'The amount of money you are allowed to spend. Going over budget makes families sad.'],
  contingency: ['Contingency', 'Extra money saved for surprises, like finding a big rock. Builders usually save about 10%.'],
  survey: ['Survey', 'A surveyor measures the land and finds the exact property lines. Metal pins in the ground mark the corners.'],
  perc_test: ['Perc Test', 'A percolation test checks how fast water soaks into the soil, to see if a septic system will work there.'],
  soil_test: ['Soil Test', 'An engineer checks if the soil is strong enough to hold up a house.'],
  zoning: ['Zoning', 'Town rules about what can be built where — like homes here, stores over there.'],
  setback: ['Setback', 'How far a house must be from the road and the property lines.'],
  floodplain: ['Floodplain', 'Low land near a river or creek that can flood. Building there is risky and costs more!'],
  well: ['Well', 'A deep hole drilled into the ground to pump up water.'],
  aquifer: ['Aquifer', 'Water stored underground inside rock and sand, like a giant sponge.'],
  septic: ['Septic System', 'A buried tank that holds the waste from toilets and drains, plus a drain field that lets cleaned water soak into the ground.'],
  utilities: ['Utilities', 'Services a house needs: electricity, water, sewer, gas, and internet.'],
  blueprints: ['Blueprints', 'Detailed drawings that show exactly how to build the house.'],
  floor_plan: ['Floor Plan', 'A drawing of the house from above that shows where every room goes.'],
  square_feet: ['Square Feet', 'How we measure floor size. A room 10 feet wide and 12 feet long is 10 × 12 = 120 square feet.'],
  permit: ['Building Permit', 'Official permission from the town to build. The permit must be posted at the job site.'],
  inspection: ['Inspection', 'A town inspector checks the work to make sure it is safe and follows the building code.'],
  building_code: ['Building Code', 'The rule book for building safe houses. Inspectors check the code.'],
  call811: ['Call 811', 'Before you dig, call 811! They mark buried pipes and wires so nobody digs into them.'],
  flag_colors: ['Utility Flag Colors', 'RED = electric, YELLOW = gas, BLUE = water, GREEN = sewer, ORANGE = phone & internet, WHITE = where you plan to dig.'],
  clearing: ['Clearing', 'Removing trees, bushes and stumps where the house will go.'],
  silt_fence: ['Silt Fence', 'A black fabric fence that keeps muddy water from washing off the job site.'],
  erosion: ['Erosion', 'When water or wind carries soil away.'],
  temp_power: ['Temporary Power', 'A power pole set up at the job site so workers can plug in their saws and tools.'],
  dumpster: ['Dumpster', 'A giant trash bin. Building a house makes a LOT of scraps!'],
  layout: ['Layout', 'Marking exactly where the house will go on the ground.'],
  batter_boards: ['Batter Boards', 'Little wooden fences at each corner that hold strings showing where the walls go.'],
  excavator: ['Excavator', 'A big digging machine with an arm and a bucket.'],
  frost_line: ['Frost Line', 'How deep the ground freezes in winter. Footings go BELOW it — otherwise freezing, swelling water in the soil could push the house up (frost heave)!'],
  footing: ['Footing', 'The wide concrete base under the foundation walls. It spreads the weight out, like snowshoes.'],
  rebar: ['Rebar', 'Steel bars inside concrete that make it much stronger — like bones inside your body.'],
  forms: ['Forms', 'Wooden or metal molds that hold wet concrete in shape until it hardens.'],
  concrete: ['Concrete', 'A mix of cement, sand, gravel and water that hardens like stone.'],
  curing: ['Curing', 'The chemical reaction that makes concrete hard. It takes time — about a week to be strong enough to build on.'],
  basement: ['Basement', 'A foundation with tall walls that make an underground floor. Common where winters are cold.'],
  crawl: ['Crawl Space', 'A short foundation that leaves a low space under the house — you have to crawl in there!'],
  slab: ['Slab', 'A foundation that is just a thick flat layer of concrete right on the ground. Common where it is warm.'],
  anchor_bolts: ['Anchor Bolts', 'Bolts set into the concrete that hold the wooden walls tight to the foundation.'],
  vapor_barrier: ['Vapor Barrier', 'Thick plastic that stops moisture from the ground coming up into the house.'],
  waterproofing: ['Waterproofing', 'A coating on foundation walls that keeps water out.'],
  drain_tile: ['Drain Tile', 'A pipe with holes around the bottom of the foundation that carries water away.'],
  backfill: ['Backfill', 'Putting dirt back around the foundation after it is built.'],
  grading: ['Grading', 'Shaping the ground so it slopes away from the house and rain drains away.'],
  sill_plate: ['Sill Plate', 'Treated wood that sits right on top of the foundation. Treated means bugs and rot can\'t hurt it.'],
  joist: ['Joist', 'Long boards that hold up a floor, set side by side like the rungs of a ladder.'],
  subfloor: ['Subfloor', 'Big boards glued and nailed on top of joists. The real floor goes on top later.'],
  framing: ['Framing', 'Building the wooden skeleton of the house.'],
  stud: ['Stud', 'The upright boards inside a wall, usually spaced 16 inches apart.'],
  header: ['Header', 'A strong beam above a window or door that carries the weight around the opening.'],
  truss: ['Truss', 'A factory-built triangle frame that holds up the roof. Triangles are the strongest shape!'],
  crane: ['Crane', 'A machine with a long arm that lifts heavy things high up.'],
  pitch: ['Roof Pitch', 'How steep a roof is. A "6 in 12" roof goes up 6 inches for every 12 inches across.'],
  sheathing: ['Sheathing', 'Boards nailed over the frame that make the house stiff and strong.'],
  osb: ['OSB', 'Oriented Strand Board — wood chips glued and pressed into big sheets.'],
  flashing: ['Flashing', 'Metal or sticky tape around windows, doors and roofs that makes water flow the right way.'],
  double_pane: ['Double-Pane Window', 'Two layers of glass with gas between them. It keeps heat in better.'],
  house_wrap: ['House Wrap', 'A paper-like fabric that stops rain and wind but lets moisture escape.'],
  underlayment: ['Underlayment', 'A waterproof layer under the shingles — the roof\'s second raincoat.'],
  shingles: ['Shingles', 'Overlapping pieces that cover a roof. Water runs over them like fish scales.'],
  dried_in: ['Dried In', 'When the roof, windows and doors are on, so rain can\'t get inside. A big milestone!'],
  rough_in: ['Rough-In', 'Putting pipes, wires and ducts inside the walls BEFORE the walls are covered.'],
  pex: ['PEX Pipe', 'Bendy plastic water pipe. Red is for hot water and blue is for cold.'],
  drain_vent: ['Drain & Vent', 'Drain pipes slope downhill so water flows away. Vent pipes go through the roof and let air in, so drains don\'t glug.'],
  hvac: ['HVAC', 'Heating, Ventilation and Air Conditioning — keeps the house warm, cool and fresh.'],
  ductwork: ['Ductwork', 'Metal or flexible tubes that carry air to each room.'],
  circuit: ['Circuit', 'A loop of wire that electricity travels around. Each circuit has its own breaker.'],
  breaker_panel: ['Breaker Panel', 'The box where electricity comes in. Breakers switch off automatically if too much power flows.'],
  gfci: ['GFCI Outlet', 'A special outlet near water that shuts off super fast to stop shocks.'],
  insulation: ['Insulation', 'Fluffy material in walls and attics that keeps heat from escaping.'],
  r_value: ['R-Value', 'A number for how well insulation works. Bigger number = warmer house.'],
  drywall: ['Drywall', 'Boards made of gypsum and paper that make the inside walls and ceilings.'],
  joint_compound: ['Joint Compound ("Mud")', 'A paste spread over drywall seams and screws, then sanded smooth.'],
  siding: ['Siding', 'The outside covering of the walls, like vinyl, wood or fiber-cement.'],
  soffit_fascia: ['Soffit & Fascia', 'Fascia is the board along the roof edge. Soffit covers the underside of the roof overhang and lets the attic breathe.'],
  gutter: ['Gutter', 'A channel on the roof edge that catches rain and sends it to downspouts.'],
  caulk: ['Caulk', 'A gooey sealant that fills cracks and gaps so water and air can\'t get in.'],
  meter: ['Electric Meter', 'A device that measures how much electricity the house uses.'],
  control_joint: ['Control Joint', 'A line cut into concrete so if it cracks, it cracks there in a straight line.'],
  primer: ['Primer', 'The first coat that helps paint stick and look even.'],
  template: ['Template', 'An exact pattern of the cabinets, used to cut countertops that fit perfectly.'],
  trim: ['Trim', 'Wood pieces like baseboards and door casings that cover gaps and look nice.'],
  flooring: ['Flooring', 'The top layer you walk on: wood, tile, vinyl or carpet.'],
  trim_out: ['Trim-Out', 'When plumbers, electricians and HVAC come back to put on fixtures, outlets and covers.'],
  smoke_detector: ['Smoke Detector', 'Beeps loudly if there is smoke. Required in every bedroom!'],
  thermostat: ['Thermostat', 'The control on the wall that tells the furnace or A/C when to turn on.'],
  sod: ['Sod', 'Grass that comes in rolls, like a carpet, with the roots and soil already attached.'],
  punch_list: ['Punch List', 'A list of small things to fix at the end, like a scuff or a sticky door.'],
  co: ['Certificate of Occupancy', 'The paper from the town that says the house is safe to live in. No CO, no move-in!'],
  closing: ['Closing', 'The meeting where papers are signed and the keys are handed to the new owners.'],
  loan: ['Construction Loan', 'Most families borrow money from a bank to build a house and pay it back over many years. Borrowing MORE means paying back more, so going over budget is a big deal!'],
  change_order: ['Change Order', 'A written change to the plan after building starts. It usually costs extra money and time.'],
  safety: ['Job Site Safety', 'Hard hats, safety glasses, gloves and boots keep workers safe. Safety always comes first!'],
  weather_delay: ['Weather Delay', 'Days when rain, snow or cold stop outdoor work. Builders plan extra time for them.'],
};

